import type { BankItem, Difficulty } from './types';

/**
 * More grade 3-5 grammar, spelling and comprehension items (Massachusetts
 * 2017 ELA framework: L.3-5.1, L.3-5.2, RL/RI.3-5), so these topics repeat
 * less often. Difficulty 1/2/3 = grade 3/4/5. Same rules and topic keys as
 * readingBank.ts; every prompt is unique across the combined bank (see
 * readingBankMoreReading.test.ts).
 */
function q(
  topic: string,
  difficulty: Difficulty,
  prompt: string,
  answer: string,
  wrong: string[],
  explanation: string,
): BankItem {
  return { topic, difficulty, prompt, answer, wrong, explanation };
}

